insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p46', 'allemand', '3AS', 11, 46, 'L2 3AS p46 — Zum Schreiben : Kombinieren (Freud · Emir Abdelkader · Brecht · Baya · Skandrani) + Biografie-Tabelle', E'Zum Schreiben\n1. Kombinieren Sie.\n1. Sigmund Freud (1856 - 1939) · 2. Emir Abdelkader (1808 - 1883) · 3. Bertholt Brecht (1898 - 1956) · 4. Baya (1931 - 1998) · 5. Mustapha Skandrani (1920 - 2005)\na) Komponist · b) Malerin · c) Psychoanalytiker · d) Kämpfer und Dichter · e) Schriftsteller\nLösungsraster : 1 = c · 2 … · 3 … · 4 … · 5 …\n2. Suchen Sie die Informationen und schreiben Sie eine Biografie (Gruppenarbeit).\nTabelle : Günter Grass (erhielt Nobelpreis 1999) · Mohamed Dib (Schriftsteller) · Mouloud Feraoun (gestorben 1962) · Aicha Haddad (1937 · gestorben 2005) · Ludwig van Beethoven (6. Sinfonie)\nSpalten : Geburtsdatum · Was ist er / sie · wichtigste Ereignisse · gestorben · Werke\n3. Erzählen Sie kurz über einen Dichter, Schriftsteller oder Künstler, den Sie gern haben.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p47', 'allemand', '3AS', 11, 47, 'L2 3AS p47 — Informationen : Die Festspiele in Deutschland (Beethovenfest Bonn · Bayreuth Wagner · Berlin)', E'Informationen\nDie Festspiele in Deutschland sind kein Privileg der großstädte ; sie werden auch in vielen kleinen Orten veranstaltet, die oft eine besondere Atmosphäre vermitteln, wie zum Beispiel Schwetzingen mit seinem Rokoko-Theater.\nAllein der Musik sind über 100 Festspiele gewidmet : Bonn feiert alle 3 Jahre im September sein Internationales Beethovenfest, für Augsburg ist im August und September, Richard Wagner - Festspiele in Bayreuth werden seit 1876 veranstaltet…\nDie deutschen Festspiel-Veranstalter legen besonders Wert auf die internationale Ausrichtung ihrer Aktivitäten : das Internationale Jugend-Festspieltreffen in Bayreuth und das Festival der Weltkulturen in Berlin.\nFotos : Wagnershaus', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p48', 'allemand', '3AS', 11, 48, 'L2 3AS p48 — Wortschatz L2 (30 Substantive · 4 Adjektive · 11 Verben)', E'Wortschatz\nSubstantive : e Abschaffung(en) · r Rechtsanwalt(¨e) · r Dichter(-) · r Dirigent(en) · r Einfluss(¨e) · e Entstehung(en) · r Erfolg(e) · r Erzieher(-) · r Forscher(-) · r Frieden · e Forschung(en) · e Geige(n) · r Krieg(e) · s Klavier(-) · s Konzert(e) · r Künstler(-) · r Maler(-) · e Malerei · r Nobelpreis(e) · s Publikum · r Schauspieler(-) · r Schriftsteller(-) · e Schulden · s Theaterstück(e) · e Tournee(n) · r Vertreter(-) · e Wissenschaft(en) · r Wissenschaftler(-) · s Werk(e) · r Zuschauer(-)\nAdjektive : begabt · begeistert · berühmt · mitschuldig\nVerben : auf/wachsen · aus/geben · begleiten · erhalten · ernennen · hinterlassen · kämpfen für + Akkusativ · komponieren · richten · zielen auf + Akkusativ · zurück/kehren', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p49', 'allemand', '3AS', 12, 49, 'L3 3AS p49 — Der technische Fortschritt (ouverture : Auto · Shuttle · Labor · Astronaut · Rakete)', E'Lektion 3 — Der technische Fortschritt (ouverture)\nFotos : Auto · Space-Shuttle im All · Computer-Labor · Astronaut · Rakete\nBanner : Der technische Fortschritt', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p50', 'allemand', '3AS', 12, 50, 'L3 3AS p50 — Text : Der technische Fortschritt + Richtig/falsch (4) + Ergänzen (5)', E'Der technische Fortschritt\nDie Menschen haben den technischen Fortschritt in den Dienst ihres Wunsches nach mehr Sicherheit und Bequemlichkeit gestellt und laufen die Gefahr, ihre Existenzgrundlage zu zerstören.\nNatürlich bietet der technische Fortschritt den Menschen unglaublich große Möglichkeiten : Satelliten und Raumstationen in das All und auf andere Planeten zu senden, den Kosmos zu entdecken, menschliche Organe zu verpflanzen, gefährliche Krankheiten zu bekämpfen und zu heilen, schneller zu reisen, mehr Komfort und Luxus in den Häusern zu bringen.\nMan kann seine Gesundheit vernachlässigen : Es gibt Apotheker, Ärzte, Chirurgen, Zahnärzte, usw.\nMan kann Papier verschwenden, Apparate kaputt machen, Gegenstände zerbrechen und Nahrung wegwerfen - die Geschäfte sind ja voll, um das alles zu ersetzen.\nFotos : Das Flugzeug · Der Laser\n1. Richtig oder falsch ? Kreuzen Sie an.\n- Der technische Fortschritt verhilft den Menschen zu einem besseren Leben.\n- Der technische Fortschritt bildet keine Gefahr.\n- Der technische Fortschritt erlaubt dem Menschen, andere Planeten zu entdecken.\n- Die Fortschritte in der Medizin verlängern dem Menschen die Lebensdauer.\n2. Ergänzen Sie.\n- … bietet zahlreiche Möglichkeiten.\n- Der Mensch hat den … entdeckt.\n- Heutzutage können viele … verpflanzt werden.\n- Der Mensch handelt … und …\n- Der moderne Mensch … das Papier.\n(verschwenden · sorglos und unbedacht · Kosmos · Der technische Fortschritt · Organe)', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
